import {caseDeepDive} from './use-case-depth.js';
const e=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const docs={lifecycle:['Lifecycle deployment','https://learn.microsoft.com/en-us/entra/id-governance/lifecycle-workflows-deployment'],access:['Employee access deployment','https://learn.microsoft.com/en-us/entra/architecture/governance-deployment-employee-access'],device:['Windows enrollment planning','https://learn.microsoft.com/en-us/intune/device-enrollment/windows/guide'],external:['External ID solution planning','https://learn.microsoft.com/en-us/entra/external-id/customers/concept-planning-your-solution'],auth:['Authentication deployment planning','https://learn.microsoft.com/en-us/entra/identity/authentication/how-to-deploy-phishing-resistant-passwordless-authentication'],architecture:['Microsoft deployment plans','https://learn.microsoft.com/en-us/entra/architecture/deployment-plans']};
export const companyStories={
 jordan:{company:'A hotel group brings an agency guest-services lead onto its payroll while he continues working at the same properties.',before:'HR creates an employee record while procurement still owns the contractor record. Separate tickets can leave Jordan with duplicate accounts, overlapping permissions or missing reservations access on his first employed shift.',outcome:'A controlled change of employment relationship, with the right history and application access preserved where the chosen identity model supports it.',owners:'HR owns the effective date and employee identifier; procurement closes the contract; IAM owns account correlation; property and application owners approve access changes.',prerequisites:'A stable person identifier, a documented source-of-authority transition, an inventory of application account keys, and an agreed rule for which contractor permissions must end.',deploy:['Reconcile the contractor and employee records before changing either account. Document whether the supported path retains the directory object or requires migration of application associations.','Pilot one property and one application. Test the target identity, claims, licenses and permissions using a scheduled employment change.','Sequence employee access and contractor removal around the effective date. Route ambiguous identity matches or failed application updates to an operator.','Expand by application after the owners accept the results. Monitor duplicate accounts, missed transitions and permissions retained beyond their approved overlap.'],proof:'Jordan can perform the employee task, cannot retain contractor-only access, and every account or application change traces back to an approved person match.',metric:'Measure failed first-shift sign-ins, duplicate identities and time to remove obsolete contractor access. Establish a baseline before agreeing targets.',fallback:'Pause the next migration wave if identity matching is uncertain. Restore only explicitly approved access; do not recreate broad contractor permissions as a shortcut.',question:'Which system decides when a contractor becomes an employee, and which applications would break if the account identifier changed?',reference:'lifecycle',moments:['Before the handover, the IAM analyst resolves conflicting records with HR and procurement. The decision is which identity to retain and which application associations must be moved.','At the transition, an operator verifies the approved source change and checks each provisioning result. A successful directory update does not prove downstream applications accepted it.','The property manager approves the employee role and property scope. Compare old and new permissions and remove exceptions that no longer have a business owner.','Jordan starts his shift in the actual reservations application. Verify a business action, the expected role and the audit trail; an Entra sign-in alone is insufficient.']},
 sofia:{company:'A hospitality employer hires frontline staff every week across properties with small local IT teams.',before:'A new starter arrives before the account, device and work applications are ready. The supervisor lends another person’s session or spends the first shift chasing tickets.',outcome:'Sofia receives a prepared device and completes her own supported sign-in before beginning work.',owners:'HR provides complete hire data; the manager confirms property and role; endpoint engineering prepares devices; IAM owns account and authentication readiness; service desk handles exceptions.',prerequisites:'Reliable hire dates and manager/property attributes, selected device ownership model, required application licenses, and an identity-verified bootstrap process.',deploy:['Define the minimum hire attributes and reject incomplete records into an owned exception queue. Map each job and property to approved baseline access.','Run pre-hire tasks against a pilot population and verify task results before promising readiness. Stage the device, required apps and policies.','Rehearse first sign-in with the authentication methods supported by Sofia’s device and workplace. Prepare a controlled recovery route for missing or lost credentials.','Roll out property by property. Give managers a readiness checklist and make failed tasks visible to the team that can resolve them.'],proof:'Sofia signs in as herself on the assigned device and completes a role-appropriate task. An unrelated property or privileged operation remains unavailable.',metric:'Track first-day readiness, time from arrival to useful work, and onboarding support contacts; separate device delays from identity delays.',fallback:'Hold the device or account handover when readiness fails. Use a documented operational workaround that does not require sharing another employee’s credentials.',question:'What must be ready before a new starter reaches the property, and who owns each failed readiness check?',reference:'lifecycle',moments:['Before arrival, HR and the manager correct missing property and role data. The onboarding team checks task completion and resolves the exception before the start date.','At pickup, endpoint support validates the assigned device, management enrollment and required applications. Enrollment and compliance are checked separately.','Sofia opens the work application and performs a normal task. The application owner verifies the role and property scope instead of accepting a visible app tile as proof.','During registration, support verifies Sofia’s identity and uses an eligible bootstrap method. Test the chosen stronger method and a lost-device recovery scenario before broad enforcement.']},
 nadia:{company:'A company hires remote integration specialists for time-limited projects and ships laptops directly to their homes.',before:'The laptop may arrive before the account or policies are ready. Contractor access is extended informally, while authentication and device problems cross several support teams.',outcome:'Nadia starts remotely with a managed device and approved access that has a clear sponsor and end date.',owners:'Procurement owns contract dates; the project sponsor approves scope and extensions; endpoint engineering owns enrollment; IAM owns authentication and access policies.',prerequisites:'An eligible registered device, tested internet enrollment path, enrollment permissions and licensing, sponsor details, application access inventory and an authoritative contract end date.',deploy:['Pilot the complete out-of-box experience on the actual supported hardware and network conditions, including the apps required to finish setup.','Validate any external authentication provider against the relevant Entra method support, policy scope and recovery process. Do not assume an existing third-party app satisfies every authentication strength.','Publish a time-bound access package where appropriate in the workforce tenant. Define approval, renewal, expiry and owner notification.','Test end-of-contract removal in each target system. Expand only after remote support can diagnose enrollment, authentication and authorization separately.'],proof:'Nadia completes remote setup and performs the approved project task; a denied resource and an expired assignment both behave as designed.',metric:'Track successful remote starts, setup duration, overdue sponsor decisions and remaining access after contract expiry.',fallback:'Pause rollout for enrollment failures and retain a support path. Any temporary access extension needs an owner, a reason and a new expiry.',question:'Can the sponsor extend work without silently extending every application permission?',reference:'device',moments:['At home, Nadia starts a registered laptop on a normal internet connection. Observe installation and enrollment failures rather than presenting the assigned Autopilot profile as the finished experience.','At sign-in, verify that the external method is eligible and actually offered to Nadia. Inspect the resulting authentication details and the recovery option if the provider is unavailable.','During the engagement, the sponsor reviews the requested apps and expiry. Test one authorized resource and one outside the approved project.','When the contract ends, the owner checks package expiry plus any direct or out-of-band assignments. Device return, session handling and downstream access require their own actions.']},
 sam:{company:'A hotel operates a shared front-desk workstation around the clock with different staff on successive shifts.',before:'Repeated prompts interrupt guest service, and unfinished browser or application sessions can expose one shift’s data to the next employee.',outcome:'Sam works through his shift with an attributable identity, a tested recovery path and a clean handover.',owners:'Front-office operations defines shift needs; endpoint engineering owns the shared-device configuration; IAM owns sign-in policy; application owners own session termination; service desk owns recovery.',prerequisites:'A deliberate Windows account model, supported kiosk applications, known federation dependencies, separate Windows/browser/application session requirements and a rehearsed offline procedure.',deploy:['Map every session boundary and choose a supported shared-PC or kiosk configuration for the actual application. A shared Windows session must not imply a shared business identity.','Pilot sign-in and Conditional Access with representative shifts. Review report-only results before a controlled enforcement change; measure actual prompts separately.','Delegate recovery to the narrowest supported role and scope. Rehearse identity verification, privileged activation and the audit trail with service desk staff.','Test shift handover, lost connectivity and reconnection on the real device. Roll out in waves with a property support owner and known-good configuration.'],proof:'After Sam exits, the next worker cannot retrieve his app data, reopen his session or inherit his permissions. Audit events identify the correct worker.',metric:'Measure avoidable prompts per shift, recovery time, failed handovers and offline incidents without trading away session isolation.',fallback:'Remove a failing device from service or restore its approved configuration. Do not fix friction by disabling controls for all frontline users.',question:'What exactly closes at shift end: Windows, the browser, the business app, or all three?',reference:'device',moments:['At clock-in, follow Sam through the federation redirect and back to the application. Establish which system authenticates him and which system issues the app token.','During the shift, compare report-only policy evaluation with the prompts Sam actually sees. Enforce a scoped policy only after representative shift testing.','When access fails, the support operator verifies Sam and activates the scoped role if required. Demonstrate that an unrelated property or privileged account cannot be reset.','At handover, sign out of every required layer and sign in as the next worker. Check cookies, cached content and application sessions, including after a network outage.']},
 tom:{company:'A facilities contractor finishes a maintenance engagement, but several property systems still have direct assignments.',before:'An end date is recorded in procurement, yet the directory account remains enabled. Different teams assume another team removed access.',outcome:'The access owner makes a documented decision and verifies removal across the actual resource inventory.',owners:'Procurement confirms the engagement ended; the sponsor resolves exceptions; IAM investigates automation; resource owners verify application removal; security handles suspicious residual activity.',prerequisites:'An authoritative end date, a complete access inventory, named reviewers, policy scope and execution history, and a defined process for extensions.',deploy:['Compare the engagement record with current directory, group, package and application access. Separate active exceptions from stale permissions.','Trace the lifecycle trigger, scope, schedule and task outcomes. Correct the missed control in a pilot; avoid treating an edited date as completed offboarding.','Run a scoped access review with an accountable reviewer and an explicit policy for unanswered reviews. Verify whether decisions have actually been applied.','Check direct assignments and application sessions after removal. Add reconciliation so missed events generate owned exceptions.'],proof:'A reviewer decision links to executed changes and a denied post-removal application attempt, with unresolved systems explicitly listed.',metric:'Track overdue access, elapsed time from end date to removal, unanswered reviews and failed removal tasks.',fallback:'Route uncertain cases to the sponsor and security owner. Any extension has a documented purpose and expiry; a completed review alone is not removal evidence.',question:'Who would notice if the contract end date were correct but no control acted on it?',reference:'access',moments:['At contract end, compare procurement’s record with Tom’s actual account and application access. Establish the gap without assuming the cause.','During investigation, trace scope, scheduling, task failures and manual assignments. Identify which team owns the missing control and the affected population.','At decision time, the reviewer sees the business context and evidence. Apply the approved outcome and verify the result in each application, not only the review page.']},
 kwame:{company:'A hospitality group needs a consistent departure process across HR, identity, devices and property applications.',before:'Disabling an account is treated as closure even when application sessions, local accounts, delegated rights or equipment remain unresolved.',outcome:'Kwame’s departure has a defined completion standard and a traceable record of remaining exceptions.',owners:'HR authorizes the departure time; IAM executes identity actions; application owners terminate app access; endpoint operations handles equipment; the offboarding owner signs off the evidence.',prerequisites:'Confirmed departure timing, identity and entitlement inventory, session behavior for each critical app, data ownership/retention decisions and a named incident escalation path.',deploy:['Define different authorized runbooks for routine departures and urgent access termination. Agree timing, notifications and ownership with HR and security.','Pilot disablement, entitlement removal and supported session-revocation actions, then test the actual behavior of critical applications.','Handle application-owned accounts, delegated access and devices explicitly. Separate preservation of business data from removal of the departing person’s access.','Reconcile completed actions with the inventory. Close the case only when required checks pass or an accountable owner accepts a documented exception.'],proof:'Evidence records the departure signal, each action, its result and a check of remaining access. Token/session behavior is verified rather than assumed instantaneous.',metric:'Measure time to terminate critical access, incomplete application tasks and departures closed with unresolved exceptions.',fallback:'Escalate failed critical removals through the incident process. Retry safely, avoid deleting needed business records, and preserve the action history.',question:'What evidence would convince an auditor that the person lost access, rather than merely that a workflow ran?',reference:'lifecycle',moments:['At departure, HR’s authorized signal sets the timing. Check the correct person and current state before running the approved process.','To close access, inspect directory state, entitlements and application sessions separately. Test critical resources and record systems that do not honor immediate revocation.','To close the case, assemble a timeline with linked records and named exceptions. Confirm equipment and business-data handling are assigned even when they are outside Entra.']},
 lena:{company:'A multi-property hotel operator gives approved suppliers a portal to coordinate work without making every vendor a workforce employee.',before:'Supplier staff email work requests and share credentials. A recognized sign-in alone does not establish which company or properties the person is allowed to see.',outcome:'Leo registers or signs in through the branded application and sees only work authorized for his approved vendor relationship.',owners:'The digital product team owns the portal; procurement approves vendor relationships; IAM owns External ID; the API team enforces permissions; support owns recovery and security monitors abuse.',prerequisites:'A registered application in an external tenant, configured user flow and supported sign-in methods, exact redirect URIs, an API token-validation design and a trusted vendor-to-property mapping.',deploy:['Choose the supported authentication approach and configure the application, branding and user flow. Collect only attributes needed by the business; self-entered company names must not grant access.','Bind the authenticated subject to a procurement-approved vendor relationship in a trusted store. Validate tokens and resource permissions in the API on every protected request.','Pilot registration, returning-user sign-in, configured recovery and supported MFA paths. Include duplicate registrations, rejected vendors and cross-company access attempts.','Add monitoring, support, privacy/retention decisions and extension/API availability checks. Expand after the product and security owners accept both allowed and denied scenarios.'],proof:'A real account signs in and accesses an assigned order; the server denies a different vendor’s order. Correlate identity logs with application records.',metric:'Measure registration completion, time to approved vendor access, recovery completion and unauthorized request denials. Sample workshop clicks are not production measurements.',fallback:'If a trusted entitlement service fails, deny the protected operation and provide a support path. Do not fall back to granting access from an unverified form field.',question:'Who approves the vendor-to-property relationship, and where is that authorization enforced?',reference:'external',moments:['Leo arrives with a work task. Walk from branded entry to verified identity, then to the approved vendor relationship and the permitted work order. The live Supplier Desk demonstrates this path; the embedded workshop workspace remains a rehearsal aid.']}
};
export function companyPlaybook(id,index=0){const p=companyStories[id];if(!p)return '';const ref=docs[p.reference];return `<section class="company-playbook" aria-label="Company deployment playbook"><div class="company-heading"><span class="company-kicker">FROM THE STORY TO YOUR COMPANY</span><h3>How a company would put this to work</h3><p>${e(p.company)}</p><small>Illustrative production design · not a claim about the current lab</small></div><div class="company-outcomes"><div><b>The operational problem</b><p>${e(p.before)}</p></div><div><b>The intended outcome</b><p>${e(p.outcome)}</p></div></div><div class="company-moment"><b>At this point in the working day</b><p>${e(p.moments[index]||p.moments[0])}</p></div><details><summary>Deploy it · prerequisites, owners and rollout</summary><div class="company-detail"><h4>Who owns the result</h4><p>${e(p.owners)}</p><h4>Before configuration starts</h4><p>${e(p.prerequisites)}</p><ol>${p.deploy.map(x=>`<li>${e(x)}</li>`).join('')}</ol><p class="company-reference">Product planning reference: <a href="${ref[1]}" target="_blank" rel="noopener noreferrer">${ref[0]} ↗</a>. Confirm current feature availability, tenant model and licensing for the chosen design.</p></div></details><details><summary>Operate it · acceptance evidence, measures and recovery</summary><div class="company-detail"><h4>Acceptance evidence</h4><p>${e(p.proof)}</p><h4>Measure the business result</h4><p>${e(p.metric)}</p><h4>If the rollout fails</h4><p>${e(p.fallback)}</p></div></details><div class="company-discussion"><b>Bring it back to the client</b><p>${e(p.question)}</p></div></section>`;}

// Original illustrative deployment recommendations, not live tenant findings.
// Fields: company need, design/setup, pilot, acceptance, operations owner.
export const casePlans={
1:['An acquired hotel keeps familiar employee email identifiers while standardizing directory sign-in.','Inventory identifiers, verify ownership of routable domains and evaluate supported alternate-login behavior for each app and authentication path.','Use a small employee cohort; test home-realm discovery, duplicate identifiers and legacy clients before communications go out.','The approved identifier reaches the correct account in every critical app; ambiguous identifiers fail safely.','IAM and messaging teams own identifier changes and help-desk guidance.'],
2:['A legacy directory uses an internal suffix that employees cannot use reliably with cloud services.','Map legacy UPNs to a verified routable suffix and inventory dependencies on old identifiers. Preserve stable account matching through the supported sync configuration.','Test representative synced accounts, devices and application NameID dependencies before changing a business unit.','Cloud sign-in and downstream account matching work without duplicate users or unexpected mailbox/application changes.','Directory engineering owns mapping; application owners approve dependency changes.'],
3:['Employees need stronger sign-in that fits laptops, shared desks and mobile work.','Build a persona/device compatibility matrix; select supported phishing-resistant methods and design identity verification, bootstrap and recovery.','Target a small registration group, validate success and loss/recovery, then apply scoped enforcement after readiness checks.','Authentication details show the intended method; users can recover through an approved route and unready users are accounted for.','IAM owns method policy; endpoint and service desk teams own readiness and recovery.'],
4:['Contractors already use a supported third-party authentication service.','Verify provider integration, licensing, supported clients and policy compatibility; configure the external method for an explicit population.','Test enrollment, prompt eligibility, provider failure and recovery with actual policy requirements.','The intended method appears and the sign-in record meets the required control; possession of a third-party app alone is not proof.','IAM and the provider owner monitor failures and certificate or integration changes.'],
5:['A business serves employees, partner collaborators and customers with different identity needs.','Classify populations by relationship and application: workforce, workforce B2B or external-tenant CIAM. Review current licensing and billing guidance for each.','Map representative users and apps before moving populations; validate governance, authentication and residency requirements.','Each population has a documented tenant choice, supported controls and an approved licensing assessment.','Architecture and commercial owners review new population types and expected activity.'],
6:['A partner needs business access without inheriting unrestricted internal access.','Design inbound collaboration, trust and Conditional Access in the correct tenant; explicitly decide which partner MFA/device claims can be trusted.','Start with a scoped test population and report-only policies; test trusted and untrusted partner/device combinations before enforcement.','Actual policy results match the intended allow/block decisions. Report-only observations remain separate from enforced results.','Security and partner-access owners review trust changes and exceptions.'],
7:['A cloud-led organization still has applications that depend on on-premises AD.','Inventory required AD objects and attributes; select and verify a supported provisioning architecture. Do not assume ordinary directory sync provisions arbitrary cloud users back to AD.','Prove one supported end-to-end path, source authority, matching and update behavior before expanding.','A controlled source change reaches the intended AD-dependent app without duplicate objects or conflicting writes.','Hybrid identity engineering owns connector health, reconciliation and documented limitations.'],
8:['Regional support teams should assist their own properties without controlling the whole enterprise.','Map support duties to administrative units and supported scoped roles; use eligible privileged access where appropriate. Check role and object limitations.','Test a permitted reset in the local scope and an attempted action outside it using the real operator account.','Both the allowed action and the rejected out-of-scope action are recorded. An administrative unit is not a universal application isolation boundary.','Privileged-access owners review scope membership and role assignments.'],
9:['A contractor joins payroll and needs continuity in essential business systems.','Correlate person records, choose the supported identity transition, assign authoritative attributes and inventory application keys and entitlements.','Schedule one conversion with HR, procurement and app owners; verify new access and removal of superseded access.','Approved continuity is demonstrated in the application, with obsolete permissions removed and matching decisions recorded.','HR and IAM own exceptions; application owners validate business continuity.'],
10:['New suppliers need self-service onboarding to a branded vendor application.','Register the app in the external tenant, associate the sign-up/sign-in flow, configure branding/methods and exact redirect URIs, and define required attributes.','Test fresh and duplicate registrations with prepared identities; keep vendor approval separate from user-entered company information.','A real account is created and the application grants only the access backed by its trusted approval store.','Product, IAM and procurement own signup completion and vendor approval queues.'],
11:['A returning local-password vendor forgets credentials outside service-desk hours.','Confirm the account type and supported recovery flow, verification channel, branding and support fallback. Email-OTP sign-in is a different journey.','Rehearse recovery with a dedicated test account and the actual verification channel; test failure and return-to-app behavior.','Recovery completes and subsequent sign-in succeeds for the intended account without exposing the password in the demo.','Customer support owns recovery escalation and monitors repeated failures.'],
12:['A business wants stronger verification before an external user performs a sensitive operation.','Separate workforce B2B from external-tenant capabilities. Verify supported MFA methods, policies and app transaction-step-up integration for the selected model.','Test the ordinary action and the sensitive action with eligible users. Validate actual enforcement rather than relying on a report-only policy.','The protected action requires the intended evidence and is rejected if requirements are unmet; MFA at initial sign-in alone does not prove transaction step-up.','Security and application owners own assurance requirements and exception handling.'],
13:['A frontline worker loses a method and a regional operator must restore access.','Select the narrowest supported role and scope, configure privileged activation where appropriate, and define identity verification and recovery procedures.','Use disposable test methods on a prepared account; test out-of-scope denial and privileged-account restrictions.','An authorized reset is auditable, the worker re-registers successfully and unrelated accounts remain outside operator reach.','Service desk owns execution; privileged-access management reviews activation and reset records.'],
14:['Applications need trusted property and business-role context in tokens.','Define the claims contract and trusted source; configure the applicable claims mapping or supported custom extension. Secure the extension API and plan failure behavior.','Test normal, missing, stale and conflicting attributes, plus extension timeout and unavailable-source cases.','Issued claims match trusted records and the API independently enforces access; failed enrichment cannot grant broader permissions.','App and identity teams version the claims contract and monitor extension reliability.'],
15:['Long-tenured employees accumulate groups and tokens become difficult for apps to process.','Inventory group claims and application needs; prefer an explicit role model where appropriate and implement supported group-overage handling if used.','Test an ordinary user and a high-membership user against the real app and any directory lookup dependency.','Authorization remains correct when groups are omitted due to overage; the app does not treat missing claims as unrestricted access.','Application owners monitor token/lookup failures and maintain role mappings.'],
16:['An enterprise needs a shared view of workforce, partner, customer and legacy identity boundaries.','Document tenant purposes, authoritative sources, trust, directories, applications, integration ownership and data flows.','Trace one person from each population through authentication, authorization, provisioning and offboarding.','Every trust and provisioning edge has an owner and supported design; customer and workforce controls are not assumed interchangeable.','Architecture owns the diagram and reviews it when applications or populations change.'],
17:['An application moves from a legacy federation service to Entra without losing user associations.','Inventory SAML metadata, certificates, NameID, attributes, assignments, provisioning and app-side account matching. Agree a cutover and restoration procedure.','Use a nonproduction instance or supported pilot connection; test representative roles and session/logout behavior.','The same intended business account is reached, claims are correct and unassigned users are denied.','The app owner and IAM coordinate certificate renewal, cutover communications and rollback.'],
18:['A company replaces older authentication methods with a stronger supported method.','Identify registrations and device eligibility, target method policies, define secure bootstrap and prepare identity-verified recovery.','Migrate a small cohort, confirm new registrations and sign-in before retiring old methods for that cohort.','Users satisfy the intended policy and can recover; obsolete methods are removed only after the approved transition criteria pass.','IAM tracks adoption; service desk owns reenrollment exceptions and user communications.'],
19:['An enterprise migrates a portfolio of apps while some domains remain federated.','Inventory domain authentication, app dependencies and provisioning separately; define coexistence and supported migration units.','Pilot a controlled population or app using the supported mechanism; preserve a tested recovery path for authentication outages.','Users reach the intended identity provider and application without account mismatch across coexistence paths.','Federation and application owners monitor redirect failures and execute approved cutover waves.'],
20:['Property devices need updates without disrupting check-in and guest service.','Define device groups, update rings, maintenance expectations, restart behavior, deadlines and compliance reporting for each operating pattern.','Start with representative pilot hardware and apps; assess operational impact before broad deployment.','Devices install the intended updates and report health; deployment assignment alone does not establish patch compliance.','Endpoint operations owns failure remediation and approved pause/rollback decisions.'],
21:['Corporate hires receive a laptop that prepares itself for work.','Confirm hardware registration, Windows eligibility, enrollment scope, licenses, network access, Autopilot profile, apps and Enrollment Status Page behavior.','Run a full reset/out-of-box test on an eligible pilot device with a prepared user and realistic network conditions.','Enrollment, required app installation and first useful work complete; profile configuration is not out-of-box proof.','Endpoint engineering owns setup failures and support escalation.'],
22:['Remote contact-center staff must start without visiting an office.','Design internet-only enrollment and verify home-network reachability, required apps, device registration and authentication bootstrap.','Ship or simulate a real pilot device and test setup from outside the corporate network, including interrupted downloads.','The remote user finishes setup and performs the contact-center task with the intended device controls.','Remote support owns recovery and replacement logistics; endpoint engineering owns enrollment policy.'],
23:['A named frontline worker has a dedicated managed device.','Choose the supported join/enrollment model, assign the correct primary user and target required apps, configuration and compliance.','Test a representative device with the assigned worker and verify application access after policy delivery.','The right user/device association, management state and actual compliance are visible and the work task succeeds.','Endpoint operations and property managers own handover and replacement.'],
24:['A front desk shares hardware across many workers and shifts.','Choose the Windows and application identity models explicitly; configure supported shared-PC/kiosk settings and session cleanup for each app.','Test successive workers, browser restart, lock/unlock and abandoned sessions on the actual workstation.','The next worker cannot recover the previous worker’s data or session; business actions remain attributable.','Endpoint and app owners jointly own session isolation and property support.'],
25:['A property must understand what remains usable during a network outage.','Document cached Windows sign-in, cloud authentication and application offline capabilities separately; define approved offline work and reconnection behavior.','Use an isolated test device and a controlled outage; compare returning and first-time users, then reconnect.','Observed behavior matches the runbook; a cached Windows login is not presented as working cloud authentication or fresh authorization.','Property operations owns continuity; endpoint/app teams own recovery checks.'],
26:['A supplier uses a shared property kiosk to open a vendor work item.','Keep the Windows session separate from External ID application identity; configure app sign-out, browser cleanup and server-side vendor permissions.','Sign in as Leo, exit, then test a different vendor and a restarted browser.','No previous vendor data remains accessible and the API rejects cross-vendor resources.','The vendor app and endpoint owners jointly own cleanup and kiosk support.'],
27:['Seasonal turnover creates large numbers of short-lived accounts.','Choose workforce versus external placement by actual relationship and application needs, not tenure alone. Connect authoritative hire/leave signals to scoped lifecycle controls.','Exercise join, extension, cancellation and departure events for one seasonal group, including delayed or corrected source records.','Each account has an owner and correct lifecycle state, with missed events surfaced for reconciliation.','HR/procurement and IAM own source quality and lifecycle exceptions.'],
28:['A worker covers two properties temporarily and must not gain access to every location.','Maintain effective-dated property assignments in a trusted source and translate them into app roles or validated claims with server-side checks.','Test a scheduled second-property assignment, its expiry and attempts to access an unrelated property.','Allowed properties match the effective assignment; stale sessions/tokens and refreshed authorization behave according to the documented design.','Property managers approve scope; app owners enforce and audit it.'],
29:['An enterprise partner needs controlled access to a business portal.','Choose B2B collaboration or CIAM based on the portal’s requirements; for the workforce B2B reference, configure guest onboarding, assignment requirements and application roles.','Test an approved guest, an unassigned guest and a removed assignment in the target application.','Only approved partner users perform the permitted actions; successful authentication alone gives no business entitlement.','Partner sponsor and app owner own approval, review and termination.'],
30:['An organization needs to change upstream identity providers without redesigning every application.','Document the federation protocol and trust at each boundary, stable subject mapping, certificates and application token validation.','Test a supported alternate path with prepared users and compare account matching, claims and failure behavior.','The application accepts only its intended issuer/audience and preserves the correct identity across the approved federation path.','Federation engineering owns metadata/certificates; apps own validation and authorization.'],
31:['A contractor returns for repeat engagements and needs newly approved access each time.','Use sponsored, time-bound workforce collaboration access where appropriate; define renewal, expiry and review policies and distinguish account retention from active entitlement.','Let a test assignment expire and request a new engagement with a different scope; inspect any direct assignments.','Returning sign-in does not restore expired privileges automatically; renewed access has an approved scope and expiry.','The sponsor owns renewal decisions; governance operations verifies expiry and review application.'],
32:['A campaign or supplier event creates a short burst of external registrations.','Plan external-tenant signup, supported methods, minimal attributes, abuse controls, application/API capacity and data retention.','Load-test only authorized test environments and rehearse email delivery, duplicate accounts and upstream/API failure with synthetic users.','Registration and the approved business task meet agreed service targets under tested load; volume does not bypass authorization.','Product and operations own capacity, abuse monitoring and cleanup.'],
33:['An authenticated person attempts an action outside their business role.','Define resource and operation permissions, validate API tokens and enforce authorization server-side using trusted identity and entitlement data.','Test allowed and denied operations, changed resource identifiers, expired assignments and direct API requests.','The API denies unauthorized requests even when the UI button is hidden or a user is successfully signed in.','Application security and app owners maintain authorization tests and role changes.'],
34:['A security team must explain how a sign-in relates to a business action.','Collect identity and app audit records with stable subject identifiers, timestamps and relevant correlation IDs; define access, retention and alert ownership.','Run a known sign-in and app action, then trace the records across systems while accounting for ingestion delay and clock differences.','An investigator can connect the actual user/action/result and clearly identify missing evidence; identity logs alone do not prove resource access.','Security operations and app owners maintain logging coverage and incident runbooks.']
};
export function caseDeployment(id){const a=casePlans[id];if(!a)return '';return `<section class="company-playbook case-deployment"><div class="company-heading"><span class="company-kicker">REAL-COMPANY APPLICATION</span><h3>When and how to deploy this</h3><small>Illustrative implementation guidance · validate against your environment</small></div>${[['When a company uses it',a[0]],['Design and prerequisites',a[1]],['Pilot and deployment',a[2]],['Acceptance evidence',a[3]],['Who runs it',a[4]]].map(([title,text],i)=>`<div class="case-deploy-step"><span>0${i+1}</span><div><h4>${title}</h4><p>${e(text)}</p></div></div>`).join('')}${caseDeepDive(id)}<div class="company-discussion"><b>Before broad rollout</b><p>Agree the population, owner, success criteria and rollback or containment plan. Verify current licensing and supported product behavior. Expand only after the pilot’s allowed, denied and failure scenarios pass.</p></div></section>`;}
